sys_ws_operation.operation_script:
(function process(request, response) {
  var PO_TABLE = "x_2056099_indust_0_production_order";
  var body = {};
  try { body = JSON.parse(request.body.dataString); } catch (e) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Invalid request body" } });
    return;
  }
  var sysId = body.sys_id;
  if (!sysId) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "sys_id is required" } });
    return;
  }
  var gr = new GlideRecord(PO_TABLE);
  if (!gr.get(sysId)) {
    response.setStatus(404);
    response.setBody({ result: { success: false, error: "Production Order not found" } });
    return;
  }
  if (gr.getValue("active") != "1") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Production Order is inactive" } });
    return;
  }
  var currentStatus = gr.getValue("status");
  if (currentStatus == "completed") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Production Order is already completed" } });
    return;
  }
  if (currentStatus == "cancelled") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Cannot complete a cancelled order" } });
    return;
  }
  if (currentStatus != "in_production") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Order must be In Production to complete. Current status: " + gr.getDisplayValue("status") } });
    return;
  }
  var produced = parseFloat(gr.getValue("quantity_produced")) || 0;
  if (produced <= 0) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Cannot complete order with zero production. Record production quantities first." } });
    return;
  }
  var planned = parseFloat(gr.getValue("quantity_planned")) || 0;
  var finalRemaining = planned - produced;
  gr.setValue("quantity_remaining", finalRemaining.toString());
  gr.setValue("actual_end_date", new GlideDateTime().getValue());
  gr.setValue("status", "completed");
  gr.update();

  // --- Link to Production Schedule: transition in_progress → completed ---
  var SCHED_TABLE = "x_2056099_indust_0_prod_sched";
  var schedGr = new GlideRecord(SCHED_TABLE);
  schedGr.addQuery("production_order", sysId);
  schedGr.addQuery("active", true);
  schedGr.addQuery("status", "in_progress");
  schedGr.query();
  var scheduleCompleted = false;
  while (schedGr.next()) {
    schedGr.setValue("status", "completed");
    schedGr.update();
    scheduleCompleted = true;
  }

  response.setBody({
    result: {
      success: true,
      message: "Production completed. Produced: " + produced + "/" + planned + (finalRemaining > 0 ? " (" + finalRemaining + " under-produced)" : " (fully produced)"),
      record: {
        sys_id: gr.getValue("sys_id"),
        number: gr.getValue("number") || gr.getValue("sys_id"),
        status: gr.getValue("status"),
        statusDisplay: gr.getDisplayValue("status"),
        quantityPlanned: gr.getValue("quantity_planned"),
        quantityProduced: gr.getValue("quantity_produced"),
        quantityRemaining: gr.getValue("quantity_remaining"),
        actualStartDate: gr.getDisplayValue("actual_start_date"),
        actualEndDate: gr.getDisplayValue("actual_end_date"),
        scheduleCompleted: scheduleCompleted
      }
    }
  });
})(request, response);
